# Full file path to your CSV
file_path <- "C:/Users/ns01288/Documents/upregulated_genes_by_condition.csv"

# Read the CSV file
data <- read.csv(file_path, stringsAsFactors = FALSE)

# Initialize an empty list to store all genes
all_genes <- c()

# Loop through the columns containing gene lists (starting from the 3rd column)
for (col_index in 3:ncol(data)) {
  for (row_index in 1:nrow(data)) {
    gene_list <- data[row_index, col_index]
    
    # Check for empty cells (length zero) and NA
    if (length(gene_list) > 0 && !is.na(gene_list)) { 
      if (gene_list != "") {
        genes <- trimws(unlist(strsplit(gene_list, ","))) # Split and trim spaces
        all_genes <- c(all_genes, genes)
      }
    }
  }
}

# Count gene occurrences
gene_counts <- table(all_genes)

# Filter for genes appearing 5 or more times
frequent_genes <- names(gene_counts[gene_counts >= 5])

# Print the frequent genes
cat("Genes appearing 5 or more times:\n")
print(frequent_genes)
