# --- 2. Read and Process Tarney Data ---

tarney_file_path <- "C:/Users/ns01288/OneDrive - University of Surrey/data using disertation/Total_Proteome_wong_et_al_Tarney_et_al.xlsx"
Tarney_data <- read_excel(tarney_file_path, sheet = "Tarney_et_al_Total_Proteome")

tarney_genes <- Tarney_data %>%
  filter(TP_Tarney_et_al_logFC_LGSOCvsTube > 0.5) %>%
  dplyr::select(GS) %>%
  pull(GS)

# --- 3. Find Common Genes ---

common_genes <- intersect(frequent_genes, tarney_genes)

cat("\nCommon genes between Wong and Tarney:\n")
print(common_genes)

# --- 4. Pathway Analysis (GO Enrichment) ---

if (length(common_genes) > 0) {
  # Convert gene symbols to Entrez IDs
  entrez_ids <- bitr(common_genes, fromType = "SYMBOL", toType = "ENTREZID", OrgDb = "org.Hs.eg.db")
  
  if (nrow(entrez_ids) > 0) {
    go_enrich <- enrichGO(
      gene = entrez_ids$ENTREZID,
      OrgDb = org.Hs.eg.db,
      keyType = "ENTREZID",
      ont = "BP", # Biological Process, change to "MF" or "CC" for other ontologies
      pAdjustMethod = "BH",
      pvalueCutoff = 0.01,
      qvalueCutoff = 0.05,
      readable = TRUE
    )
    
    if (!is.null(go_enrich)) {
      print(go_enrich)
      # Optional: Plot the results
      barplot(go_enrich, showCategory = 10)
      dotplot(go_enrich, showCategory = 10)
    } else {
      cat("\nNo significant GO terms found.\n")
    }
  } else {
    cat("\nCould not convert gene symbols to Entrez IDs.\n")
  }
} else {
  cat("\nNo common genes found for pathway analysis.\n")
}
