library(readr)
library(readxl)
library(dplyr)
library(clusterProfiler)
library(org.Hs.eg.db)
library(patchwork)
library(ggplot2)

# --- Function to Perform GO Enrichment and Plot ---

perform_go_analysis <- function(gene_list, title_prefix) {
  if (length(gene_list) > 0) {
    entrez_ids <- bitr(gene_list, fromType = "SYMBOL", toType = "ENTREZID", OrgDb = "org.Hs.eg.db")
    
    if (nrow(entrez_ids) > 0) {
      go_enrich <- enrichGO(
        gene = entrez_ids$ENTREZID,
        OrgDb = org.Hs.eg.db,
        keyType = "ENTREZID",
        ont = "BP",
        pAdjustMethod = "BH",
        pvalueCutoff = 0.01,
        qvalueCutoff = 0.05,
        readable = TRUE
      )
      
      if (!is.null(go_enrich)) {
        barplot_plot <- barplot(go_enrich, showCategory = 10) + ggtitle(paste(title_prefix, "Barplot")) + theme(plot.title = element_text(hjust = 0.5))
        dotplot_plot <- dotplot(go_enrich, showCategory = 10) + ggtitle(paste(title_prefix, "Dotplot")) + theme(plot.title = element_text(hjust = 0.5))
        return(list(barplot = barplot_plot, dotplot = dotplot_plot))
      } else {
        cat("\nNo significant GO terms found.\n")
        return(NULL)
      }
    } else {
      cat("\nCould not convert gene symbols to Entrez IDs.\n")
      return(NULL)
    }
  } else {
    cat("\nNo common genes found for pathway analysis.\n")
    return(NULL)
  }
}

